export type WidgetIcon = keyof typeof WIDGET_ICON_PATHS;

export function resolveWidgetIconKey(raw: string | undefined): WidgetIcon | null {
  if (!raw) return null;
  const k = raw.trim().toLowerCase();
  if (k in WIDGET_ICON_PATHS) return k as WidgetIcon;
  if (k.includes('fire') || k.includes('burn') || k.includes('flame')) return 'flame';
  if (k.includes('ice') || k.includes('frost') || k.includes('cold') || k.includes('snow') || k.includes('froz')) return 'snowflake';
  if (k.includes('zap') || k.includes('shock') || k.includes('light') || k.includes('bolt')) return 'lightning';
  if (k.includes('bleed') || k.includes('blood')) return 'bleeding-wound';
  if (k.includes('drop')) return 'drop';
  if (k.includes('shield') || k.includes('armor') || k.includes('ward') || k.includes('cover')) return 'shield';
  if (k.includes('hidden') || k.includes('invis')) return 'invisible';
  if (k.includes('eye')) return 'eye';
  if (k.includes('sleep') || k.includes('moon') || k.includes('uncons')) return 'sleepy';
  if (k.includes('restrain') || k.includes('grapple') || k.includes('grab') || k.includes('root')) return 'grab';
  if (k.includes('stun') || k.includes('daze') || k.includes('knock')) return 'knockout';
  if (k.includes('fear') || k.includes('terror')) return 'terror';
  if (k.includes('blind')) return 'blindfold';
  if (k.includes('deaf') || k.includes('hear') || k.includes('silen')) return 'hearing-disabled';
  if (k.includes('charm') || k.includes('magic') || k.includes('spark') || k.includes('bless') || k.includes('curse')) return 'magic';
  if (k.includes('prone') || k.includes('slow') || k.includes('foot')) return 'footprints';
  if (k.includes('sword') || k.includes('attack') || k.includes('rage')) return 'sword';
  if (k.includes('poison') || k.includes('acid') || k.includes('toxic')) return 'poison';
  if (k.includes('dead') || k.includes('death') || k.includes('skull') || k.includes('down')) return 'skull';
  if (k.includes('web')) return 'spider-web';
  return null;
}